<div class="tamu-grid">
    <div class="field"><label for="surat_tugas">Surat tugas</label><input class="input" type="file" id="surat_tugas" name="surat_tugas[]" accept="application/pdf,image/jpeg,image/png,image/webp" multiple><p class="tamu-hint">PDF atau foto. Maksimal 3 berkas, masing-masing 5 MB.</p></div>
    <div class="field"><label for="dokumentasi">Foto kunjungan</label><input class="input" type="file" id="dokumentasi" name="dokumentasi[]" accept="image/jpeg,image/png,image/webp" multiple><p class="tamu-hint">Maksimal 5 foto, masing-masing 5 MB. Total unggahan 20 MB.</p></div>
</div>
<div class="tamu-upload-state" data-upload-state hidden role="status" aria-live="polite"><strong data-upload-label></strong><progress data-upload-progress max="100" value="0" aria-label="Kemajuan unggahan"></progress></div>
